  void ApplyLanguage(Control parent){foreach(Control c in parent.Controls){if(c is Label||c is Button||c is TabPage||c is CheckBox||c is GroupBox){string source;if(!originalWords.TryGetValue(c,out source)){source=Words.Source(c.Text);originalWords[c]=source;}c.Text=T(source);}if(!(c is DataGridView))ApplyLanguage(c);}}
