  void PersistProjectPaths(){session.Server=server.Text;session.Client=client.Text;session.ItemFile=catalog.Source;if(sessionReady&&!IsTest)SaveSession();if(Directory.Exists(Path.Combine(server.Text,"Mu Editor","Item"))&&string.IsNullOrEmpty(imageFolder.Text))imageFolder.Text=Path.Combine(server.Text,"Mu Editor","Item");SetupImages();}
