  void ConnectDatabase(){if(HasDrafts()&&!DiscardDrafts())return;var cs=new SqlConnectionStringBuilder{DataSource=sqlHost.Text.Trim(),InitialCatalog=sqlDb.Text.Trim(),IntegratedSecurity=integrated.Checked,Encrypt=true,TrustServerCertificate=trust.Checked,ConnectTimeout=5,ApplicationName="MU Editor Phoenix"};if(!integrated.Checked){cs.UserID=sqlUser.Text;cs.Password=sqlPassword.Text;}var next=new Database{ConnectionString=cs.ConnectionString};next.Probe();db=next;accountTable=null;charTable=null;inventoryDraft=null;ClearRecordForms();connectionLabel.Text=T("Conectado")+"\r\n"+sqlDb.Text;connectionLabel.ForeColor=Color.FromArgb(105,218,170);RefreshPeople(false);
   string account=session.Account,character=session.Character;if(!string.IsNullOrEmpty(account)){var found=db.Search(account);if(found.Rows.Cast<DataRow>().Any(r=>r["Account"].ToString()==account)){LoadPerson(account,null);if(!string.IsNullOrEmpty(character)&&db.Characters().Rows.Cast<DataRow>().Any(r=>r["Name"].ToString()==character))LoadPerson(account,character);}}status.Text=T("Conectado")+" · "+sqlHost.Text+" / "+sqlDb.Text;SaveSession();}
