  void ClearRecordForms(){accountFields.Controls.Clear();characterFields.Controls.Clear();masterFields.Controls.Clear();currentItem=-1;inventoryDraft=null;inventoryBoard.Buffer=null;warehouseBoard.Buffer=null;inventoryBoard.Invalidate();warehouseBoard.Invalidate();}
  string Caption(string column){var names=new Dictionary<string,string>{{"memb___id","Conta"},{"Name","Personagem"},{"AccountID","Conta"},{"mail_addr","Email"},{"bloc_code","Bloqueio"},{"AccountLevel","Nível VIP"},{"AccountExpireDate","Vencimento VIP"},{"cLevel","Nível"},{"Strength","Força"},{"Dexterity","Agilidade"},{"Vitality","Vitalidade"},{"Energy","Energia"},{"Leadership","Liderança"},{"LevelUpPoint","Pontos"},{"Class","Classe"},{"MapNumber","Mapa"},{"MasterLevel","Master Level"},{"MasterPoint","Master Points"},{"ExtInventory","Inventory expansions"},{"Money","Zen"}};string value;return T(names.TryGetValue(column,out value)?value:column);}
  void RecordEditor(FlowLayoutPanel panel,DataTable table){foreach(Control old in panel.Controls.Cast<Control>().ToArray())old.Dispose();panel.Controls.Clear();if(table==null||table.Rows.Count==0){panel.Controls.Add(new Label{Text="—",AutoSize=true});return;}var row=table.Rows[0];foreach(DataColumn column in table.Columns){string name=column.ColumnName;var field=new Panel{Size=new Size(250,72),Margin=new Padding(4),BackColor=Color.FromArgb(23,33,47),Padding=new Padding(10)};field.Controls.Add(new Label{Text=Caption(name),Dock=DockStyle.Top,Height=24,ForeColor=Color.FromArgb(148,170,186)});Control input;
    if(column.DataType==typeof(DateTime)){var date=new DateTimePicker{Format=DateTimePickerFormat.Custom,CustomFormat="dd/MM/yyyy HH:mm",ShowCheckBox=true,Checked=row[column]!=DBNull.Value,Value=row[column]==DBNull.Value?DateTime.Today.AddDays(30):Convert.ToDateTime(row[column])};date.ValueChanged+=(s,e)=>row[column]=date.Checked?(object)date.Value:DBNull.Value;input=date;}
    else if(name=="bloc_code"){var check=new CheckBox{Text=Caption(name),Checked=row[column].ToString()=="1"};check.CheckedChanged+=(s,e)=>row[column]=check.Checked?"1":"0";input=check;}
    else if(column.DataType==typeof(int)||column.DataType==typeof(byte)||column.DataType==typeof(short)||column.DataType==typeof(long)){int max=name=="cLevel"?400:new[]{"Class","CtlCode","MapPosX","MapPosY"}.Contains(name)?255:name=="AccountLevel"?3:name=="ExtInventory"?2:int.MaxValue;var number=new NumericUpDown{Minimum=0,Maximum=max,ThousandsSeparator=true,Value=row[column]==DBNull.Value?0:Math.Max(0,Math.Min(max,Convert.ToDecimal(row[column])))};number.ValueChanged+=(s,e)=>row[column]=Convert.ChangeType(number.Value,column.DataType);input=number;}
    else{var text=new TextBox{Text=row[column]==DBNull.Value?"":row[column].ToString(),ReadOnly=name=="Name"||name=="memb___id",MaxLength=name=="mail_addr"?50:100};text.TextChanged+=(s,e)=>{if(!text.ReadOnly)row[column]=text.Text;};input=text;}
    input.Dock=DockStyle.Bottom;field.Controls.Add(input);panel.Controls.Add(field);
   }
  }
  bool TableDirty(DataTable edited,DataTable original){if(edited==null||original==null||edited.Rows.Count!=1||original.Rows.Count!=1)return false;return edited.Columns.Cast<DataColumn>().Any(c=>original.Columns.Contains(c.ColumnName)&&!Equals(edited.Rows[0][c],original.Rows[0][c.ColumnName]));}
  bool HasDrafts(){return TableDirty(accountTable,db.OriginalAccount)||TableDirty(charTable,db.OriginalCharacter)||TableDirty(db.MasterDraft,db.MasterOriginal)||(inventoryDraft!=null&&inventoryDraft.Dirty)||(db.Warehouse!=null&&(db.Warehouse.Dirty||Convert.ToInt32(warehouseMoney.Value)!=Convert.ToInt32(db.OriginalWarehouse.Rows[0]["Money"])));}
  bool DiscardDrafts(){return !HasDrafts()||MessageBox.Show(this,T("Alterações pendentes")+". Descartar para carregar outro registro?","MU Editor Phoenix",MessageBoxButtons.OKCancel,MessageBoxIcon.Question,MessageBoxDefaultButton.Button2)==DialogResult.OK;}
  void LoadPerson(string account,string character){if(!DiscardDrafts())return;bool same=account==db.Account;db.CrossStorageDirty=false;db.OriginalCharacter=null;db.MasterDraft=db.MasterOriginal=null;db.Warehouse=null;db.OriginalWarehouse=null;charTable=null;inventoryDraft=null;accountTable=db.LoadAccount(account);accountGrid.DataSource=accountTable;RecordEditor(accountFields,accountTable);characterFields.Controls.Clear();masterFields.Controls.Clear();
   if(character==null){var chars=db.Characters();if(chars.Rows.Count>0)character=chars.Rows[0]["Name"].ToString();}if(character!=null){charTable=db.LoadDetailedCharacter(character);charGrid.DataSource=charTable;inventoryDraft=new ItemBuffer(db.Inventory.Data);RecordEditor(characterFields,charTable);RecordEditor(masterFields,db.MasterDraft);}else db.Character="";
   var pages=db.WarehousePages();warehousePages.DataSource=pages;warehousePages.DisplayMember="Name";warehousePages.ValueMember="Number";if(pages.Rows.Count>0){db.LoadWarehouse(Convert.ToInt32(pages.Rows[0]["Number"]));warehouseMoney.Value=Convert.ToInt32(db.OriginalWarehouse.Rows[0]["Money"]);}RefreshBoards();status.Text=account+(character==null?"":" / "+character);SaveSession();
  }
  void RefreshPeople(bool refreshRecord){if(!db.Connected)throw new Exception("Conecte ao banco em Conexão e preferências.");string account=db.Account,character=db.Character;bool dirty=HasDrafts();browserLoading=true;try{accountsGrid.DataSource=db.BrowseAccounts(accountSearch.Text);charactersGrid.DataSource=db.BrowseCharacters(accountSearch.Text);foreach(var grid in new[]{accountsGrid,charactersGrid})foreach(DataGridViewColumn col in grid.Columns)col.HeaderText=Caption(col.Name);peopleLabel.Text=accountsGrid.Rows.Count+" "+T("Contas")+" · "+charactersGrid.Rows.Count+" "+T("Personagens")+"\r\nAté 1.000 resultados por lista; filtre para localizar mais.";}finally{browserLoading=false;}
   if(refreshRecord&&!dirty&&!string.IsNullOrEmpty(account)){var exists=db.Search(account).Rows.Cast<DataRow>().Any(r=>r["Account"].ToString()==account);if(exists)LoadPerson(account,db.Characters().Rows.Cast<DataRow>().Any(r=>r["Name"].ToString()==character)?character:null);}status.Text=T("Atualizado")+(dirty?" · "+T("Alterações pendentes"):"");
  }
  void SaveAccountV2(){if(accountTable==null)throw new Exception("Escolha uma conta na lista.");if(!Review(accountTable,db.OriginalAccount,db.Account))return;db.SaveAccount(accountTable);accountTable=db.OriginalAccount.Copy();RecordEditor(accountFields,accountTable);RefreshPeople(false);status.Text=T("Salvar conta")+" · OK";}
  void SaveWorkspaceV2(bool includeWarehouse){if(charTable==null&&db.Warehouse==null)throw new Exception("Escolha uma conta/personagem.");if(inventoryDraft!=null){db.Inventory.Data=(byte[])inventoryDraft.Data.Clone();db.InventoryNewItems=inventoryDraft.NewItems.ToDictionary(p=>p.Key,p=>p.Value);}bool characterDirty=TableDirty(charTable,db.OriginalCharacter)||TableDirty(db.MasterDraft,db.MasterOriginal)||(inventoryDraft!=null&&inventoryDraft.Dirty);bool wareDirty=db.Warehouse!=null&&(db.Warehouse.Dirty||Convert.ToInt32(warehouseMoney.Value)!=Convert.ToInt32(db.OriginalWarehouse.Rows[0]["Money"]));if(!characterDirty&&!wareDirty){status.Text="Nenhuma alteração.";return;}
   if(!includeWarehouse&&!characterDirty&&wareDirty)throw new Exception("Use Salvar inventário e baú para gravar alterações do baú.");if(db.CrossStorageDirty)includeWarehouse=true;string summary=db.Account+" / "+db.Character+"\r\n"+(characterDirty?T("Personagem")+" / "+T("Inventário")+"\r\n":"")+(includeWarehouse&&wareDirty?T("Baú")+"\r\n":"");if(MessageBox.Show(this,summary+"\r\nAplicar as alterações? A conta precisa estar offline.","MU Editor Phoenix",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;
   if(includeWarehouse&&db.Warehouse!=null)db.SaveWorkspace(charTable,(int)warehouseMoney.Value);else if(charTable!=null)db.SaveCharacter(charTable);else db.SaveWarehouse((int)warehouseMoney.Value);
   if(db.OriginalCharacter!=null){charTable=db.OriginalCharacter.Copy();charTable.Columns.Remove("Inventory");inventoryDraft=new ItemBuffer(db.Inventory.Data);RecordEditor(characterFields,charTable);RecordEditor(masterFields,db.MasterDraft);}RefreshBoards();RefreshPeople(false);status.Text=T("Salvar")+" · OK";
  }
  void VisualCatalogPage(){var page=Page("Catálogo de itens");var split=new SplitContainer{Size=new Size(1200,700),Dock=DockStyle.Fill,SplitterDistance=850};page.Controls.Add(split);itemsGrid=Grid(false);itemsGrid.RowTemplate.Height=58;split.Panel1.Controls.Add(itemsGrid);var bar=Bar();itemSearch.Width=260;bar.Controls.Add(itemSearch);sectionFilter.DropDownStyle=classFilter.DropDownStyle=ComboBoxStyle.DropDownList;sectionFilter.Width=120;classFilter.Width=110;bar.Controls.Add(sectionFilter);bar.Controls.Add(classFilter);classFilter.Items.AddRange(new object[]{"All","DW","DK","FE","MG","DL","SU","RF","GL","RW","SL","GC","KM","LM","IK","AL"});classFilter.SelectedIndex=0;bar.Controls.Add(Button("Importar Item.xml",()=>{string file=PickFile("Item.xml|*.xml");if(file!=null){catalog.Load(file);ShowItems("");SaveSession();}}));split.Panel1.Controls.Add(bar);var preview=new PictureBox{Dock=DockStyle.Top,Height=220,SizeMode=PictureBoxSizeMode.Zoom,BackColor=Color.FromArgb(21,31,43)};var info=new Label{Dock=DockStyle.Fill,Padding=new Padding(16),ForeColor=Color.FromArgb(166,195,212)};split.Panel2.Controls.Add(info);split.Panel2.Controls.Add(preview);itemsGrid.SelectionChanged+=(s,e)=>{if(itemsGrid.CurrentRow==null||!itemsGrid.Columns.Contains("ID"))return;int id=Convert.ToInt32(itemsGrid.CurrentRow.Cells["ID"].Value);ItemDef item;if(catalog.Items.TryGetValue(id,out item)){preview.Image=imageBank.Get(id);info.Text=item.Name+"\r\n\r\nID "+id+"  ·  "+item.Section+":"+item.Index+"\r\n"+item.Width+" × "+item.Height;}};itemSearch.TextChanged+=(s,e)=>ShowItems(itemSearch.Text);sectionFilter.SelectedIndexChanged+=(s,e)=>{if(!catalogLoading)ShowItems(itemSearch.Text);};classFilter.SelectedIndexChanged+=(s,e)=>ShowItems(itemSearch.Text);
  }
  void ShowItems(string term){if(itemsGrid==null)return;catalogLoading=true;try{string selected=sectionFilter.SelectedItem==null?"All":sectionFilter.SelectedItem.ToString();var sections=catalog.Items.Values.Select(i=>i.Section).Distinct().OrderBy(x=>x).Select(x=>x.ToString()).ToArray();if(sectionFilter.Items.Count!=sections.Length+1){sectionFilter.Items.Clear();sectionFilter.Items.Add("All");sectionFilter.Items.AddRange(sections.Cast<object>().ToArray());sectionFilter.SelectedItem=sectionFilter.Items.Contains(selected)?selected:"All";}var table=new DataTable();table.Columns.Add("Image",typeof(Image));table.Columns.Add("ID",typeof(int));table.Columns.Add("Section",typeof(int));table.Columns.Add("Index",typeof(int));table.Columns.Add("Name");table.Columns.Add("Size");int count=0;foreach(var d in catalog.Items.Values.OrderBy(i=>i.Id)){if(selected!="All"&&d.Section.ToString()!=selected)continue;if(!string.IsNullOrWhiteSpace(term)&&d.ToString().IndexOf(term,StringComparison.OrdinalIgnoreCase)<0&&d.Id.ToString()!=term)continue;string cl=classFilter.SelectedItem==null?"All":classFilter.SelectedItem.ToString();string flag;if(cl!="All"&&(!d.Attributes.TryGetValue(cl,out flag)||flag=="0"))continue;table.Rows.Add(imageBank.Get(d.Id),d.Id,d.Section,d.Index,d.Name,d.Width+" × "+d.Height);if(++count>=600)break;}itemsGrid.DataSource=table;itemsGrid.RowTemplate.Height=58;if(itemsGrid.Columns.Contains("Image")){((DataGridViewImageColumn)itemsGrid.Columns["Image"]).ImageLayout=DataGridViewImageCellLayout.Zoom;itemsGrid.Columns["Image"].Width=62;itemsGrid.Columns["Image"].DefaultCellStyle.NullValue=null;}if(itemsGrid.Columns.Contains("Name"))itemsGrid.Columns["Name"].AutoSizeMode=DataGridViewAutoSizeColumnMode.Fill;}finally{catalogLoading=false;}}
  void StoragePage(){invOption.Increment=4;var page=Page("Inventário e baú");var outer=new SplitContainer{Size=new Size(1250,700),Dock=DockStyle.Fill,SplitterDistance=850};page.Controls.Add(outer);var rewardBar=Bar();rewardBar.Controls.Add(Button("Adicionar no personagem",()=>AddReward(false)));rewardBar.Controls.Add(Button("Adicionar no baú",()=>AddReward(true)));rewardBar.Controls.Add(Button("Salvar inventário e baú",()=>SaveWorkspaceV2(true)));rewardBar.Controls.Add(Button("Cancelar item novo",()=>CancelNewReward()));page.Controls.Add(rewardBar);var storage=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=2,ColumnStyles={new ColumnStyle(SizeType.Percent,50),new ColumnStyle(SizeType.Percent,50)},RowStyles={new RowStyle(SizeType.Absolute,110),new RowStyle(SizeType.Percent,100)}};outer.Panel1.Controls.Add(storage);
   var invBar=Bar();invBar.Controls.Add(new Label{Text="Inventário",AutoSize=true});inventoryRegion.DropDownStyle=ComboBoxStyle.DropDownList;inventoryRegion.Width=180;inventoryRegion.Items.AddRange(new object[]{"Bolsa principal","Equipamentos","Expansão 1","Expansão 2","Expansão 3","Expansão 4"});inventoryRegion.SelectedIndex=0;invBar.Controls.Add(inventoryRegion);storage.Controls.Add(invBar,0,0);
   var wareBar=Bar();wareBar.Controls.Add(new Label{Text="Baú",AutoSize=true});warehousePages.DropDownStyle=ComboBoxStyle.DropDownList;warehousePages.Width=160;wareBar.Controls.Add(warehousePages);wareBar.Controls.Add(Button("Abrir baú",()=>{if(db.Warehouse!=null&&db.Warehouse.Dirty)throw new Exception("Salve o baú atual antes de trocar.");if(warehousePages.SelectedValue==null)return;db.LoadWarehouse(Convert.ToInt32(warehousePages.SelectedValue));warehouseMoney.Value=Convert.ToInt32(db.OriginalWarehouse.Rows[0]["Money"]);RefreshBoards();}));warehouseRegion.DropDownStyle=ComboBoxStyle.DropDownList;warehouseRegion.Width=160;warehouseRegion.Items.AddRange(new object[]{"Baú principal","Baú expandido"});warehouseRegion.SelectedIndex=0;wareBar.Controls.Add(warehouseRegion);storage.Controls.Add(wareBar,1,0);
   foreach(var pair in new[]{new KeyValuePair<int,ItemBoard>(0,inventoryBoard),new KeyValuePair<int,ItemBoard>(1,warehouseBoard)}){var panel=new Panel{Dock=DockStyle.Fill,AutoScroll=true,Padding=new Padding(10)};pair.Value.Location=new Point(10,10);panel.Controls.Add(pair.Value);storage.Controls.Add(panel,pair.Key,1);pair.Value.SelectedItem=(board,slot)=>SelectStorageItem(board,slot);pair.Value.Dropped=(from,s,to,t)=>Run(()=>MoveStorage(from,s,to,t));}inventoryRegion.SelectedIndexChanged+=(s,e)=>RefreshBoards();warehouseRegion.SelectedIndexChanged+=(s,e)=>RefreshBoards();
   var editor=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(14)};outer.Panel2.Controls.Add(editor);selectedItemPicture.Size=new Size(250,140);selectedItemPicture.SizeMode=PictureBoxSizeMode.Zoom;selectedItemPicture.BackColor=Color.FromArgb(20,29,41);editor.Controls.Add(selectedItemPicture);selectedItemLabel.Size=new Size(260,70);selectedItemLabel.Text="Nenhum item selecionado";editor.Controls.Add(selectedItemLabel);
   foreach(var pair in new[]{new KeyValuePair<string,NumericUpDown>("Nível",invLevel),new KeyValuePair<string,NumericUpDown>("Durabilidade",invDur),new KeyValuePair<string,NumericUpDown>("Adicional",invOption),new KeyValuePair<string,NumericUpDown>("Excellent",invExc)}){var line=new FlowLayoutPanel{Width=270,Height=34};line.Controls.Add(new Label{Text=pair.Key,Width=160,Padding=new Padding(0,5,0,0)});line.Controls.Add(pair.Value);editor.Controls.Add(line);}invLuck.ForeColor=invSkill.ForeColor=ForeColor;editor.Controls.Add(invSkill);editor.Controls.Add(invLuck);editor.Controls.Add(Button("Aplicar opções ao item",()=>{if(currentBoard==null||currentItem<0)throw new Exception("Selecione um item na grade.");currentBoard.Buffer.Options(currentItem,(int)invLevel.Value,(int)invDur.Value,invSkill.Checked,invLuck.Checked,ItemCodec25.AdditionalCode((int)invOption.Value),(int)invExc.Value);currentBoard.Invalidate();SelectStorageItem(currentBoard,currentItem);storageLabel.Text=T("Alterações pendentes");}));
   var move=Bar();move.Controls.Add(new Label{Text="Mover para slot",AutoSize=true});moveTarget.Maximum=239;move.Controls.Add(moveTarget);move.Controls.Add(Button("Mover",()=>{if(currentBoard==null)throw new Exception("Selecione um item.");MoveStorage(currentBoard,currentItem,currentBoard,(int)moveTarget.Value);}));editor.Controls.Add(move);editor.Controls.Add(Button("Transferir para outro painel",()=>TransferToOther()));editor.Controls.Add(new Label{Text="Zen / Baú",AutoSize=true});warehouseMoney.Width=220;editor.Controls.Add(warehouseMoney);storageLabel.Size=new Size(270,90);editor.Controls.Add(storageLabel);
   invGrid=Grid(false); // Compatibility with V1 project helper; the visual boards are the V2 editor.
