  void RefreshBoards(){inventoryBoard.Catalog=warehouseBoard.Catalog=catalog;inventoryBoard.Images=warehouseBoard.Images=imageBank;int region=inventoryRegion.SelectedIndex;if(region==1)inventoryBoard.Configure(inventoryDraft,0,12,true);else{int start=region<2?12:76+(region-2)*32;inventoryBoard.Configure(inventoryDraft,start,start+(region<2?64:32),false);}int warehouseStart=warehouseRegion.SelectedIndex==1?120:0;warehouseBoard.Configure(db.Warehouse,warehouseStart,warehouseStart+120,false);currentBoard=null;currentItem=-1;selectedItemPicture.Image=null;selectedItemLabel.Text=T("Nenhum item selecionado");storageLabel.Text=db.Account+(string.IsNullOrEmpty(db.Character)?"":" / "+db.Character)+"\r\n"+(HasDrafts()?T("Alterações pendentes"):"");}
  void SelectStorageItem(ItemBoard board,int slot){currentBoard=board;currentItem=slot;if(board.Buffer==null||board.Buffer.Empty(slot)){selectedItemPicture.Image=null;selectedItemLabel.Text="Slot "+slot+" · vazio";return;}var b=board.Buffer.Get(slot);int id=board.Buffer.Id(slot);selectedItemPicture.Image=imageBank.Get(id);selectedItemLabel.Text=catalog.Name(id)+"\r\nID "+id+" · Slot "+slot;invLevel.Value=(b[1]>>3)&15;invDur.Value=b[2];invSkill.Checked=(b[1]&128)!=0;invLuck.Checked=(b[1]&4)!=0;invOption.Value=4*((b[1]&3)+((b[7]&64)>>4));invExc.Value=b[7]&63;}
  void CheckInventoryArea(ItemBoard board,int slot){if(board!=inventoryBoard)return;if(slot<12||slot>=204)throw new Exception("Movimentação de equipamentos/slots especiais requer regras específicas. Edite as opções ou use as bolsas.");int expansion=slot<76?0:1+(slot-76)/64;int unlocked=charTable!=null&&charTable.Columns.Contains("ExtInventory")?Convert.ToInt32(charTable.Rows[0]["ExtInventory"]):0;if(expansion>unlocked)throw new Exception("Expansão do inventário ainda não liberada para este personagem.");}
  void MoveStorage(ItemBoard from,int source,ItemBoard to,int target){if(from.Buffer==null||to.Buffer==null)throw new Exception("Carregue personagem e baú.");CheckInventoryArea(from,source);CheckInventoryArea(to,target);if(target<to.Start||target>=to.End)throw new Exception("Destino fora da grade selecionada.");ItemBuffer.Move(from.Buffer,source,to.Buffer,target,catalog,to.Start,to.End);if(from.Buffer!=to.Buffer)db.CrossStorageDirty=true;inventoryBoard.Invalidate();warehouseBoard.Invalidate();to.Selected=target;SelectStorageItem(to,target);storageLabel.Text=T("Alterações pendentes");}
  void TransferToOther(){if(currentBoard==null||currentItem<0)throw new Exception("Selecione um item.");var target=currentBoard==inventoryBoard?warehouseBoard:inventoryBoard;CheckInventoryArea(currentBoard,currentItem);if(target.Buffer==null)throw new Exception("Carregue o outro painel.");for(int slot=target.Start;slot<target.End;slot++){if(!target.Buffer.Empty(slot))continue;var sourceCopy=new ItemBuffer(currentBoard.Buffer.Data);var targetCopy=new ItemBuffer(target.Buffer.Data);try{CheckInventoryArea(target,slot);ItemBuffer.Move(sourceCopy,currentItem,targetCopy,slot,catalog,target.Start,target.End);}catch{continue;}MoveStorage(currentBoard,currentItem,target,slot);return;}throw new Exception("Não há espaço válido na grade de destino.");}
 }
